let cloud;try{cloud=await initializeCloud();}catch(e){document.querySelector('#app').innerHTML='<main class=login-page><h1>A little connection pause.</h1><p id=boot-error></p><button class=heart-pill id=reload>Try again ♡</button></main>';document.querySelector('#boot-error').textContent=e.message;document.querySelector('#reload').onclick=()=>location.reload();throw e;}
if(cloud.enabled&&!cloud.store){loginGate(document.querySelector('#app'),cloud.client);await new Promise(()=>{});}
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=localStorage}catch{storage={getItem(){throw Error('Browser storage is unavailable')},setItem(){throw Error('Browser storage is unavailable')},removeItem(){}}}
const store=cloud.store||new Store(storage);const draftPrefix='dreamhub-draft:'+(cloud.user?cloud.user.id+':':'local:');let route=location.hash.slice(1)||'home',filter='',tab='all',search='',mobile=false,month=day().slice(0,7),selectedDate='',draw=[],editBase=null,formId='',writingType='note',pendingImport=null,focusedTask='',photo='';
const routeName=r=>groups.flatMap(g=>g[1]).find(x=>x[0]===r)?.[1]||({search:'Personal search',trash:'The little recovery room'}[r])||'Today';
const records=(type)=>active(store.state).filter(r=>!type||r.type===type);
const listFor=r=>active(store.state).filter(x=>(routeTypes[r]||[]).includes(x.type)&&(r!=='studio'||x.type!=='project'||x.tags.includes('Studio')));
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
function toast(text){$('#message').textContent=text;$('#message').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#message').classList.remove('show'),4500)}
function error(text){$('#persistent-error').hidden=false;$('#persistent-error').innerHTML=`${icon('spark')}<span>${esc(text)}</span><button data-action="dismiss-error" aria-label="Dismiss error">${icon('close')}</button>`;}
async function act(fn,message){try{await fn();$('#persistent-error').hidden=true;if(message)toast(message);render();return true}catch(e){error(e.message);return false}}
function nav(){return groups.map(([label,items],i)=>`<details ${i<2||items.some(x=>x[0]===route)?'open':''}><summary>${label}</summary><div class="navitems">${items.filter(x=>!store.state.settings.hidden.includes(x[0])).map(([id,title,ic])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${route===id?'<i>♡</i>':''}</a>`).join('')}</div></details>`).join('')}
function shell(content){const p=store.state.settings;document.body.dataset.theme=p.theme;document.body.dataset.mode=p.mode;document.body.classList.toggle('still',!p.motion);document.body.classList.toggle('compact',p.density==='compact');document.documentElement.style.colorScheme=p.theme==='midnight'?'dark':'light';$('#app').innerHTML=`<aside class="sidebar ${mobile?'open':''}"><a href="#home" class="brand"><span class="brandmark">${icon('heart')}</span><span>dreamhub<small>ARABELLA’S LITTLE UNIVERSE</small></span></a><button class="search-shortcut" data-action="search">${icon('search')}<span>Find a little something</span><kbd>⌘ K</kbd></button><nav aria-label="My spaces">${nav()}</nav><div class="sidebar-bottom"><p>For every version<br><em>of you.</em> <span>♡</span></p><a href="#settings" class="localstatus"><i></i> ${store.cloud?'Private cloud connected':'Saved on this device'}</a></div></aside><div class="page"><header class="topbar"><button class="mobilemenu iconbutton" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs"><span>My universe</span><i>/</i><strong>${routeName(route)}</strong></div><div class="topactions"><button class="modebutton" data-action="mode">${icon(p.mode==='dream'?'moon':'briefcase')}<span>${p.mode==='dream'?'Dream mode':'Command mode'}</span></button><button class="iconbutton" data-action="quick" aria-label="Quick capture">${icon('plus')}</button><button class="avatar" data-action="settings" aria-label="My settings">A</button></div></header><main id="main" tabindex="-1">${store.error?`<div class="notice danger"><strong>Your original data needs recovery.</strong><p>${esc(store.error)}. The original storage has not been replaced.</p><button data-action="raw-export">Download original data</button></div>`:''}${content}</main><footer><span>Made of little moments & big dreams.</span><span>an arabella kind of universe ${icon('heart')}</span></footer></div><button class="floating-heart" data-action="quick" aria-label="Capture a little thought">${icon('heart')}<span>a little thought?</span></button><nav class="mobilebottom" aria-label="Quick navigation"><a href="#home">${icon('home')}<span>Today</span></a><a href="#calendar">${icon('calendar')}<span>Plan</span></a><button data-action="quick" class="capture">${icon('heart')}<span>Capture</span></button><a href="#estate">${icon('spark')}<span>Explore</span></a><button data-action="menu">${icon('menu')}<span>More</span></button></nav>`;}
function heading(kicker,title,sub,addType=null){return `<section class="pageheading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${addType?heartButton(`New ${types[addType].name.toLowerCase()}`,'new',`data-type="${addType}"`):''}</section>`}
function miniTask(t){return `<div class="mini-task ${t.status==='Done'?'done':''}"><button class="taskcheck ${t.status==='Done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button><button class="tasktext" data-action="edit" data-id="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.data.project||t.tags[0]||'My life')} · ${t.minutes||15} min ${t.date?'· '+esc(t.date):''}</span></button><button class="pin ${t.favorite?'pinned':''}" data-action="favorite" data-id="${t.id}" aria-label="${t.favorite?'Unpin':'Pin'} priority">${icon('star')}</button></div>`}
function home(){const concierge=lifeSummary(active(store.state),day());const name=esc(store.state.settings.name),all=active(store.state),tasks=records('task').filter(r=>r.status!=='Done'),priorities=tasks.filter(r=>r.favorite).slice(0,3),upcoming=all.filter(r=>['event','bill','application'].includes(r.type)&&r.date>=day()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3),feel=records('mood').filter(r=>r.date===day()).at(-1),total=totals(all,day().slice(0,7));const visible=store.state.settings.mode==='gentle';return `<section class="panel" aria-label="Your life concierge"><span class="tiny-label">THE LIFE CONCIERGE ♡</span><h2>Three things that need you</h2>${concierge.next.map(miniTask).join('')||'<p>Your urgent queue is clear. ♡</p>'}<p>${concierge.blocked.length} waiting on another step · ${concierge.lowStock.length} items to restock</p></section>`+heading(new Date().toLocaleDateString('en',{weekday:'long'}).toUpperCase()+' · A LITTLE FRESH START',`Hello, <em>${name}.</em> <span class="headline-star">✧</span>`,'A little space to dream. A little structure to bloom.','note')+`<div class="homegrid"><section class="hero-panel"><div class="hero-copy"><span class="tiny-label">YOUR LIFE, IN BLOOM</span><h2>A beautiful life.<br><em>One little thing<br>at a time.</em></h2><p>You don’t have to become her overnight.<br>Make a little room for who you are today.</p><a href="#goals" class="textlink">Visit my dreams ${icon('arrow')}</a></div>${gardenArt()}<span class="hero-scribble">keep becoming, darling ♡</span></section><section class="energy-panel"><span class="tiny-label">A SOFT CHECK-IN</span><h2>How’s your<br><em>inner weather?</em></h2><p>Sunny with a little overwhelm?<br>There’s room for the whole mix.</p><div class="weatherchoices">${[['Peaceful','☼'],['Hopeful','✧'],['Tired','☾'],['Mixy','♡']].map(([m,i])=>`<button data-action="mood" data-mood="${m}" aria-label="Check in feeling ${m}"><span>${i}</span>${m}</button>`).join('')}</div><div class="energyfoot">${feel?`${esc(feel.data.feelings.map(x=>x.name).join(' + '))} <span>today</span>`:'No perfect words required.'}</div></section><section class="panel priorities"><div class="panelhead"><div><span class="tiny-label">SMALL STEPS, REAL LIFE</span><h2>Today’s little three <span>♡</span></h2></div><a href="#tasks" class="iconbutton" aria-label="All tasks">${icon('arrow')}</a></div>${priorities.length?priorities.map(miniTask).join(''):`<div class="lovelyempty">${icon('flower')}<h3>A little breathing room.</h3><p>Choose up to three tasks to keep close today.<br>Your whole life doesn’t have to fit on this list.</p><button class="softbutton" data-action="new" data-type="task">Choose my next small step ${icon('plus')}</button></div>`}<div class="panelbottom"><span>${tasks.length} open ${tasks.length===1?'possibility':'possibilities'}</span><button class="textbutton" data-action="gentle">${visible?'Return to full view':'I need a gentler day'} ↗</button></div></section><section class="panel focus-mini"><div class="panelhead"><div><span class="tiny-label">THE REST CAN WAIT</span><h2>A pocket of focus</h2></div>${icon('clock')}</div><div class="mini-clock" data-clock>${timerText()}</div><p>One task. A little time. You’ve got this.</p><button class="heart-pill" data-action="focus-start">${icon('heart')} ${store.state.timer?.running?'Pause my session':'Start a little session'}</button><a class="textlink" href="#focus">Make myself comfortable ${icon('arrow')}</a></section></div>${visible?'':`<div class="section-label"><span>A LITTLE WANDER THROUGH YOUR WORLD</span><i></i><span>✧</span></div><div class="roomtiles">${[['grimoire','The grimoire','A little practical magic','moon'],['journal','Dear, beautiful me','Meet myself on the page','book'],['treasury','Money garden','Tend to my independence','coin'],['estate','The dream estate','All my worlds, connected','home']].map(([r,t,sub,ic])=>`<a href="#${r}" class="roomtile room-${r}"><span class="room-icon">${icon(ic)}</span><h3>${t}</h3><p>${sub}</p><span class="round-arrow">${icon('arrow')}</span></a>`).join('')}</div><div class="lowergrid"><section class="panel"><div class="panelhead"><div><span class="tiny-label">ON MY LITTLE HORIZON</span><h2>What’s coming up</h2></div><a href="#calendar" class="textlink">My planner ↗</a></div>${upcoming.length?upcoming.map(r=>`<button class="horizon-row" data-action="edit" data-id="${r.id}"><span>${esc(r.date.slice(8))}<small>${new Date(r.date+'T12:00:00').toLocaleString('en',{month:'short'})}</small></span><div><strong>${esc(r.title)}</strong><small>${types[r.type].name} ${esc(r.data.time||'')}</small></div>${icon(types[r.type].icon)}</button>`).join(''):'<p class="calmempty">An open horizon. Add an appointment, a plan,<br>or something lovely to look forward to.</p>'}</section><section class="panel quotepanel"><span class="tiny-label">A NOTE FROM MY FUTURE SELF</span><blockquote>“I’m allowed to build<br>a life that feels<br><em>like mine.</em>”</blockquote><span class="signature">with love, Arabella ♡</span></section><section class="panel moneymini"><span class="tiny-label">THIS MONTH’S MONEY GARDEN</span><h2>${dollars(total.income-total.expense)}</h2><p>Income minus expenses you’ve logged.<br>Not a bank balance.</p><a href="#treasury" class="textlink">A little money moment ${icon('arrow')}</a></section></div>`}`}
function card(r){const def=types[r.type]||types.note;let extra='';if(r.type==='transaction')extra=`<strong class="amount ${r.data.direction==='Income'?'positive':''}">${r.data.direction==='Income'?'+':'−'}${dollars(r.data.amount)}</strong><small>${esc(r.data.scope)} · ${esc(r.data.category)}</small>`;if(r.type==='saving'){const target=r.data.target||0,amount=r.data.amount||0;extra=`<strong class=amount>${dollars(amount)}</strong><small>of ${dollars(target)} saved</small><div class=progress><span style="width:${target?Math.min(100,amount/target*100):0}%"></span></div>`;}if(r.type==='bill')extra=`<strong class=amount>${dollars(r.data.amount||0)}</strong><small>${esc(r.data.cadence)} · due ${esc(r.date||'when entered')}</small>`;if(r.type==='debt')extra=`<strong class=amount>${dollars(r.data.amount||0)}</strong><small>${Number(r.data.apr)||0}% APR · ${dollars(r.data.payment||0)} monthly payment</small>`;if(r.type==='goal'||r.type==='learning')extra=`<div class="progress"><span style="width:${Math.max(0,Math.min(100,Number(r.data.progress)||0))}%"></span></div><small>${Number(r.data.progress)||0}% · ${esc(r.data.milestone||r.data.practice||'At my own pace')}</small>`;if(r.type==='mood')extra=`<div class="feeling-tags">${r.data.feelings.map(f=>`<span>${esc(f.name)} <i>${f.intensity}/5</i></span>`).join('')}</div><small>${esc(r.energy)} energy${r.data.need?' · Need: '+esc(r.data.need):''}</small>`;if(r.type==='habit'){const n=habitCount(r);extra=`<div class="habitflowers">${Array.from({length:Math.min(7,r.data.target)},(_,i)=>`<span class="${i<n?'bloomed':''}">✿</span>`).join('')}</div><div class="cardactions"><small>${n}/${r.data.target} · ${esc(r.data.rhythm)}</small><button class="softbutton" data-action="habit-log" data-id="${r.id}">Log a little care ${icon('plus')}</button></div>`;}return `<article class="recordcard ${r.type==='mood'?'moodcard':''}"><div class="recordhead"><span class="record-icon">${icon(def.icon)}</span><span>${esc(r.date||'Date unknown')} · ${esc(r.type==='application'?r.data.company||def.name:def.name)}</span><button class="iconbutton ${r.favorite?'pinned':''}" data-action="favorite" data-id="${r.id}" aria-label="${r.favorite?'Unfavorite':'Favorite'} ${esc(r.title)}">${icon('heart')}</button></div><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button>${r.data.url&&safeUrl(r.data.url)?`<a class=textlink href="${esc(safeUrl(r.data.url))}" target=_blank rel="noopener noreferrer">Open saved resource ${icon('arrow')}</a>`:''}${r.body?`<p class="recordbody">${esc(r.body.slice(0,240))}${r.body.length>240?'…':''}</p>`:''}${extra}${r.data.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(r.data.photo)?`<img class="memory-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}" loading="lazy">`:''}<div class="recordmeta">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}${r.links.length?`<span class="tag">${r.links.length} linked</span>`:''}<span class="status">${esc(r.status)}</span></div><div class="cardactions"><button class="textbutton" data-action="edit" data-id="${r.id}">Open my page ↗</button>${['note','idea'].includes(r.type)?`<button class="textbutton" data-action="convert" data-id="${r.id}">Make a task</button>`:''}<button class="iconbutton" data-action="trash" data-id="${r.id}" aria-label="Move ${esc(r.title)} to trash">${icon('trash')}</button></div></article>`}
function empty(type){return `<div class="emptylarge"><div class="emptybloom">${icon(types[type].icon)}<span>✧</span><i>♡</i></div><h2>A little space for ${types[type].plural.toLowerCase()}.</h2><p>No catching up. No perfect starting point.<br>Just a fresh little page, whenever you’re ready.</p>${heartButton('Make my first entry','new',`data-type="${type}"`)}</div>`}
function beautySanctuary(){const date=selectedDate||day(),rs=active(store.state),due=dueRituals(date,rs),done=completedRituals(rs,date),products=rs.filter(r=>r.type==='beauty'),selected=['All','Skin','Hair','Body','Grooming','Wellness','Home','Life admin'];return heading('THE SOFT-LIFE SANCTUARY','My beauty <em>rituals.</em>','Care for my skin, hair, body and peace of mind — without turning self-care into another job.','beauty')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY DAILY CARE ♡</span><h2>${date===day()?'Today’s':'Selected day’s'} little rituals</h2></div><span class="tag">${due.filter(x=>x.done).length}/${due.length} complete</span></div><p>Morning and evening basics first. On low-energy days, cleansing, moisturizing, sunscreen and oral care are enough. Nothing here requires expensive products.</p><div class="centeractions"><button class="softbutton" data-action="beauty-day" data-offset="-1">← Previous day</button><strong>${esc(date)}</strong><button class="softbutton" data-action="beauty-day" data-offset="1">Next day →</button></div>${due.map(r=>`<div class="category-row"><div><strong>${esc(r.name)}</strong><small>${esc(r.when)} · ${r.minutes} min</small></div><button class="softbutton" data-action="beauty-complete" data-id="${esc(r.id)}" ${r.done?'disabled':''}>${r.done?'✓ Done':'Log ritual ♡'}</button></div>`).join('')}</section><section class="panel"><div class="panelhead"><div><span class="tiny-label">THE COMPLETE RITUAL LIBRARY</span><h2>My grown-woman care menu</h2></div><span class="tag">${beautyRituals.length} rituals</span></div><p>Choose the care you want. You can save a customized version to your beauty cabinet, edit the steps and track products separately.</p><div class="tabs" id="beauty-filters">${selected.map(x=>`<button data-action="beauty-filter" data-category="${esc(x)}" class="${(beautyCategory||'All')===x?'selected':''}">${esc(x)}</button>`).join('')}</div>${beautyRituals.filter(r=>(beautyCategory||'All')==='All'||r.category===beautyCategory).map(r=>`<details class="panel"><summary><strong>${esc(r.name)}</strong> <span class="tag">${esc(r.when)} · ${r.minutes} min</span></summary><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="caption">${esc(r.note)}</p><button class="softbutton" data-action="beauty-save" data-id="${esc(r.id)}">Save editable ritual ♡</button></details>`).join('')}</section><section class="panel"><div class="panelhead"><h2>My beauty cabinet</h2><span class="tag">${products.length} entries</span></div><p>Keep products, appointments, patch-test notes and routines together. Personal photos stay private; they are not uploaded to the public repository.</p><div class="centeractions"><button class="heart-pill" data-action="new" data-type="beauty">Add a product or routine ♡</button></div>${products.length?products.slice(0,30).map(r=>`<div class="category-row"><div><strong>${esc(r.title)}</strong><small>${esc(r.data?.category||'Beauty')} · ${esc(r.data?.routine||'')}</small></div><button class="softbutton" data-action="edit" data-id="${r.id}">Edit</button></div>`).join(''):'<p class="calmempty">Your cabinet is ready whenever you are.</p>'}</section>`;}
let beautyCategory='All';
function housekeepingPage(){const today=day(),due=rhythmDue(records('home'),today),done=rhythmCompleted(records('home'),today),d=homeForDay(today),all=records('home').filter(r=>r.data.category==='Cleaning & care'),tasks=weeklyHome.flatMap(w=>w.tasks.map(t=>({day:w.day,title:t})));return heading('MY HOUSE, MY PEACE','The housekeeping <em>sanctuary.</em>','A gentle rotating schedule for laundry, linens, cleaning and decluttering.','home')+`<section class="panel"><span class="tiny-label">TODAY’S RESET · ${esc(d.day)}</span><h2>${esc(d.name)}</h2><p>Start with one tiny action. Missed tasks can wait without guilt.</p>${d.tasks.map(t=>`<button class="softbutton" data-action="home-add" data-title="${esc(t)}">${icon('plus')} ${esc(t)}</button>`).join('')}</section><section class="panel"><h2>My weekly home rhythm</h2><div class="wardrobe-grid">${weeklyHome.map(w=>`<article class="panel"><h3>${esc(w.day)} · ${esc(w.name)}</h3><p>${w.tasks.map(esc).join(' · ')}</p></article>`).join('')}</div></section><section class="panel"><h2>My cleaning & decluttering records</h2>${all.map(r=>`<button class="softbutton" data-action="edit" data-id="${r.id}">${esc(r.title)} · ${esc(r.status)}</button>`).join('')||'<p>Start by adding a task above.</p>'}</section>`;}
let outfitSeed=0;function cluelessCloset(){const items=records('wardrobe'),clean=items.filter(eligibleForOutfit),outfit=outfitSuggestion(items,'Any',outfitSeed);return heading('THE CLUELESS CLOSET','My virtual <em>wardrobe.</em>','Photograph each item whenever you’re ready. The wardrobe and styling system are ready for your collection.','wardrobe')+`<section class="panel"><span class="tiny-label">THE OUTFIT GENERATOR ♡</span><h2>What shall I wear?</h2><p>Only clean, available clothing is considered. Dresses or a top and bottom are paired with shoes when available.</p><div class="wardrobe-grid">${outfit.pieces.map(r=>`<article class="panel">${r.data.photo?`<img loading="lazy" class="closet-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}">`:''}<h3>${esc(r.title)}</h3><p>${esc(r.data.brand||'Brand not set')} · ${esc(r.data.size||'Size not set')}</p></article>`).join('')||'<p>Outfit previews will appear once you add your own clothes.</p>'}</div><p>${outfit.complete?'A complete outfit from your closet.':'Add clean shoes and either a dress or a top and bottom to create a complete look.'}</p><button class="heart-pill" data-action="closet-shuffle">Try another ♡</button></section><section class="panel"><h2>My wardrobe · ${items.length} pieces</h2><p>${clean.length} clean and available · ${items.length-clean.length} worn, in laundry or stored</p><div class="wardrobe-grid">${items.map(r=>`<article class="panel">${r.data.photo?`<img loading="lazy" class="closet-photo" src="${esc(r.data.photo)}" alt="${esc(r.title)}">`:''}<h3>${esc(r.title)}</h3><p>${esc(r.data.brand||'Unbranded')} · ${esc(r.data.size||'Size not set')} · ${esc(r.data.laundry||'Clean')}</p><button class="softbutton" data-action="edit" data-id="${r.id}">Edit piece ♡</button></article>`).join('')||'<p>Your photo-first wardrobe is waiting for you. Add your pieces whenever you like.</p>'}</div></section><section class="panel"><h2>My Fit Passport</h2><p>Keep your real tagged sizes and fit notes here. Brand-specific size predictions will require your measurements and a verified chart; no invented universal sizes.</p></section>`;}
function modulePage(){const ts=routeTypes[route],copy=routeCopy[route]||['A LITTLE ROOM FOR THIS PART OF ME','Keep the things that matter, in your own words.'];let items=listFor(route).filter(r=>(tab==='all'||r.type===tab)&&(!filter||`${r.title} ${r.body} ${r.tags.join(' ')} ${JSON.stringify(r.data)}`.toLowerCase().includes(filter.toLowerCase())));if(route==='tasks')return taskPage();if(route==='career'||route==='studio')return pipelinePage();if(route==='grimoire')return grimoire();if(route==='treasury')return treasury();if(route==='beauty')return beautySanctuary();if(route==='sanctuary')return housekeepingPage();if(route==='wardrobe')return cluelessCloset();return heading(copy[0],titleFor(route),copy[1],ts[0])+`<div class="toolbar"><div class="tabs"><button class="${tab==='all'?'selected':''}" data-action="filter-type" data-type="all">All my pages <span>${listFor(route).length}</span></button>${ts.length>1?ts.map(t=>`<button class="${tab===t?'selected':''}" data-action="filter-type" data-type="${t}">${types[t].plural}</button>`).join(''):''}<button class="${tab==='favorites'?'selected':''}" data-action="favorites">♡ Favorites</button></div><label class="inline-search">${icon('search')}<input data-filter placeholder="Find in this space…" value="${esc(filter)}" aria-label="Filter this space"></label></div>${route==='mood'?moodSummary():''}<div id="record-results" class="recordgrid">${items.length?items.map(card).join(''):empty(ts[0])}</div>`}
function titleFor(r){const names={journal:'Dear, <em>beautiful me.</em>',diary:'My days, <em>remembered.</em>',mood:'Every feeling, <em>welcome.</em>',grimoire:'The <em>grimoire.</em>',dreams:'Somewhere in <em>my dreams.</em>',ideas:'The <em>idea garden.</em>',goals:'A life I’m <em>growing into.</em>',career:'My next <em>chapter.</em>',studio:'A. Halliwell <em>Studio.</em>',habits:'Little rituals. <em>Deep roots.</em>',sanctuary:'My <em>sanctuary.</em>',freyja:'For my girl, <em>Freyja.</em>',reviews:'The <em>Sunday salon.</em>',wishlist:'The <em>wish room.</em>',memories:'My <em>memory museum.</em>'};return names[r]||esc(routeName(r))+'.'}
function moodSummary(){const logs=records('mood').slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-7),counts={};logs.forEach(r=>r.data.feelings.forEach(f=>counts[f.name]=(counts[f.name]||0)+1));return `<section class="mood-summary"><div><span class="tiny-label">MY RECENT EMOTIONAL WEATHER</span><p>${logs.length?logs.length+' check-ins, held with care.':'Nothing to analyze. Just somewhere to land.'}</p></div><div class="feeling-tags">${Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([m,n])=>`<span>${esc(m)} · ${n}</span>`).join('')}</div><small>Counts from your last seven entries, not a diagnosis or a trend prediction.</small></section>`}
function taskPage(){const items=listFor('tasks').filter(r=>!filter||r.title.toLowerCase().includes(filter.toLowerCase()));return heading('A LITTLE STRUCTURE FOR MY BIG DREAMS','Now. Next. <em>When I’m ready.</em>','Choose a next action, give it a little time, and leave room to be human.','task')+`<div class="toolbar"><label class="inline-search">${icon('search')}<input data-filter aria-label="Filter tasks" placeholder="Find a little next step…" value="${esc(filter)}"></label><button class="softbutton" data-action="new" data-type="project">${icon('plus')} New project</button><a href="#focus" class="textlink">A little focus ↗</a></div><div class="taskboard">${['Now','Next','Later','Done'].map(status=>`<section class="boardcolumn"><div class="boardheading"><span class="status-dot ${status.toLowerCase()}"></span><h2>${status}</h2><span>${items.filter(r=>(['Now','Next','Later','Done'].includes(r.status)?r.status:'Next')===status).length}</span></div>${items.filter(r=>(['Now','Next','Later','Done'].includes(r.status)?r.status:'Next')===status).map(r=>`<div class="boardcard"><div class="cardactions"><span class="tag">${r.type==='project'?'Project':esc(r.data.priority||'Gentle')}</span><button class="iconbutton ${r.favorite?'pinned':''}" data-action="favorite" data-id="${r.id}" aria-label="Pin ${esc(r.title)}">${icon('star')}</button></div><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button>${r.data.nextAction?`<p>${esc(r.data.nextAction)}</p>`:''}<small>${r.minutes||15} min · ${esc(r.energy)} energy</small><div class="cardactions"><small>${r.date?esc(r.date):'When I’m ready'}</small><button class="taskcheck ${status==='Done'?'checked':''}" data-action="complete" data-id="${r.id}" aria-label="${status==='Done'?'Reopen':'Complete'} task">${icon('check')}</button></div></div>`).join('')}<button class="boardadd" data-action="new" data-type="task" data-status="${status}">${icon('plus')} A little next step</button></section>`).join('')}</div>`}
function grimoire(){const writings=listFor('grimoire').filter(r=>!filter||r.title.toLowerCase().includes(filter.toLowerCase()));const suits=['All cards','Major Arcana','Wands','Cups','Swords','Pentacles'];return heading('THE PRIVATE BOOK OF MY BECOMING','A little <em>practical magic.</em>','Symbols, rituals, reflections. Meaning, in your own words.','ritual')+`<section class="grimoire-banner"><div>${icon('moon')}<span class="tiny-label">THE MOON TOWER</span><h2>As above, <em>so within.</em></h2><p>A record of what you’re learning, releasing, and calling in.</p></div><div class="orbit">✦<span>☾</span>✧</div></section><div class="toolbar"><div class="tabs">${[['all','My pages'],['library','78-card library'],['draw','A reflective spread']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="grimoire-tab" data-tab="${id}">${label}</button>`).join('')}</div><button class="softbutton" data-action="new" data-type="reading">${icon('plus')} Save a reading</button></div>${tab==='library'?`<label class="inline-search">${icon('search')}<input data-tarot-search placeholder="Find a card or suit…" aria-label="Search tarot library"></label><p class="caption">Concise, original reflection notes. Your own meanings belong in your reading journal.</p><div class="tarotlibrary">${tarot.map(c=>`<article class="tarotref" data-card-name="${esc((c.name+' '+c.suit).toLowerCase())}"><span>✦ ${c.suit}</span><h3>${c.name}</h3><p><b>Upright</b> ${c.upright}</p><p><b>Reversed</b> ${c.reversed}</p></article>`).join('')}</div>`:tab==='draw'?`<section class="spreadpanel"><span class="tiny-label">PAUSE · REFLECT · CHOOSE</span><h2>A moment with <em>myself.</em></h2><p>Local random draws for reflection. They don’t predict events or outcomes.</p><div class="spreadcards">${(draw.length?draw:[null,null,null]).map((c,i)=>`<div class="tarotcard ${c?'revealed':''}"><small>${['What I’m carrying','What needs care','A possible next step'][i]}</small>${icon(c?'star':'moon')}<h3>${c?esc(c.name):'✦'}</h3><span>${c?(c.isReversed?'Reversed':'Upright'):'A little mystery'}</span>${c?`<p>${esc(c.isReversed?c.reversed:c.upright)}</p>`:''}</div>`).join('')}</div><div class="centeractions"><button class="heart-pill" data-action="draw">${icon('heart')} Draw three cards</button>${draw.length?'<button class="softbutton" data-action="save-spread">Keep this reading ↗</button>':''}</div></section>`:`<div class="recordgrid">${writings.length?writings.map(card).join(''):empty('ritual')}</div>`}<p class="caption">Spiritual content is symbolic and personal. It offers no guaranteed predictions, medical guidance, or financial advice.</p>`}
function treasury(){const all=active(store.state),t=totals(all,month),plan=store.state.budgetPlans[month]?.limit||0, bills=records('bill'),debts=records('debt'),vaults=records('saving'),monthlyBills=bills.reduce((n,r)=>n+(r.data.cadence==='Monthly'?(r.data.amount||0):r.data.cadence==='Yearly'?Math.round((r.data.amount||0)/12):0),0);return heading('MY WEALTH ERA · FREEDOM BY 30','The money <em>sanctuary.</em>','A life of freedom is built one conscious dollar at a time. ♡','transaction')+`<div class="toolbar"><div class="tabs">${[['all','Overview'],['payday','Payday ritual'],['transaction','Transactions'],['bill','Bills'],['debt','Debt lab'],['saving','Savings'],['invest','Investing']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="money-tab" data-tab="${id}">${label}</button>`).join('')}</div><label class="monthfield">Month <input type="month" id="money-month" value="${month}"></label></div><div class="money-stats"><div><span>PERSONAL INCOME LOGGED</span><strong>${dollars(t.income)}</strong><small>Recorded, not bank-verified</small></div><div><span>PERSONAL SPENDING LOGGED</span><strong>${dollars(t.expense)}</strong><small>Transactions entered this month</small></div><div><span>MONTHLY BILLS ON FILE</span><strong>${dollars(monthlyBills)}</strong><small>Check which bills remain unpaid</small></div></div>
${tab==='all'||tab==='payday'?`<section class="panel"><span class="tiny-label">THE PAYDAY RITUAL ♡</span><h2>Give every paycheck & tip a purpose</h2><p>Enter what actually arrived. Reserve outstanding essentials, minimum debt payments, taxes and your safety buffer first. Everything else gets a beautiful assignment. The plan never moves money.</p><form id="payday-form" class="formgrid"><label>Income received ($)<input required name="income" inputmode="decimal" placeholder="150.00"></label><label>Source<select name="source"><option>Paycheck</option><option>Tips</option><option>Studio owner pay</option><option>Other</option></select></label><label>Still-unpaid essential bills ($)<input required name="essentials" inputmode="decimal" value="0.00"></label><label>Minimum debt payments still due ($)<input required name="minimums" inputmode="decimal" value="0.00"></label><label>Tax reserve needed ($)<input required name="taxes" inputmode="decimal" value="0.00"></label><label>Cash safety buffer ($)<input required name="buffer" inputmode="decimal" value="0.00"></label><button class="heart-pill" type="submit">Plan my payday ♡</button></form><div id="payday-result" role="status"></div><p class="caption">All figures are editable. Enter remaining commitments for the period, not bills you've already paid. Studio gross receipts need business expenses and applicable tax reserves before they become owner pay. Allocations are suggestions, not actual transfers.</p></section>`:''}
${tab==='all'?`<div class="lowergrid twocol"><section class="panel"><h2>My financial foundations</h2><p>${bills.length} bill records · ${debts.length} debt records · ${vaults.length} savings vaults.</p><p>Build a $1,000 starter emergency reserve, work towards under 30% credit utilization, then zero interest-bearing card balances. Grow your apartment, car, travel and house funds together as income stabilizes.</p><button class="softbutton" data-action="money-starters">Add editable starter vaults & known bills ♡</button><p class="caption">Adds only missing entries. The starter figures are historical or aspirational; review before using them. No account balances are prefilled.</p></section><section class="panel"><h2>A little spending plan</h2><form id="budget-form"><label>Personal spending limit for ${month}<input name="limit" inputmode="decimal" value="${(plan/100).toFixed(2)}" required></label><button class="heart-pill">Save my plan ♡</button></form><div class="progress"><span style="width:${plan?Math.min(100,t.expense/plan*100):0}%"></span></div><p>${plan?dollars(plan-t.expense)+' remaining against entered limit.':'Set a limit to see your budget progress.'}</p></section></div>`:''}
${tab==='debt'?`<section class="panel"><h2>Credit freedom at 30% · then zero ♡</h2><form id="utilization-form" class="inlineform"><label>Card balance ($)<input name="balance" inputmode="decimal" required></label><label>Credit limit ($)<input name="limit" inputmode="decimal" required></label><button class="heart-pill">Calculate my milestone</button></form><div id="utilization-result" role="status"></div><p class="caption">Calculated separately per card. Verify the balance and credit limit; a 30% target is a milestone, not guaranteed credit-score improvement.</p><h2>Debt payoff scenario</h2><form id="debt-form" class="inlineform"><label>Balance ($)<input name="balance" inputmode="decimal" required></label><label>APR (%)<input name="apr" type="number" min="0" max="100" step=".01" required></label><label>Payment ($/month)<input name="payment" inputmode="decimal" required></label><button class="heart-pill">Explore my plan ♡</button></form><div id="debt-result" role="status"></div></section>`:''}
${tab==='invest'?`<section class="panel"><span class="tiny-label">A LONG-TERM MONEY GARDEN</span><h2>Plant for the future</h2><p>Build a safety net first, then consider retirement accounts, diversified index funds and steady automatic contributions. Keep short-term apartment and car savings out of volatile investments.</p><form id="investment-form" class="inlineform"><label>Monthly investment ($)<input name="monthly" value="100.00" inputmode="decimal" required></label><label>Years<input name="years" type="number" value="10" min="1" max="50" required></label><label>Assumed annual return (%)<input name="rate" type="number" value="7" min="0" max="15" step=".1" required></label><button class="heart-pill">See the possibility ♡</button></form><div id="investment-result" role="status"></div><p class="caption">Illustration only; not a guarantee. Excludes inflation, taxes and fees. DreamHub does not trade securities.</p></section>`:''}
<div class="toolbar"><h2>${tab==='all'?'My money pages':({bill:'Bills & subscriptions',debt:'My debt records',saving:'Savings in bloom',transaction:'Transactions',payday:'Income journal',invest:'My investment notes'}[tab])}</h2><div class="centeractions">${(tab==='all'?['bill','debt','saving']:['bill','debt','saving','transaction'].includes(tab)?[tab]:['transaction']).map(type=>`<button class="softbutton" data-action="new" data-type="${type}">${icon('plus')} ${types[type].name}</button>`).join('')}</div></div><div class="recordgrid">${listFor('treasury').filter(r=>(tab==='all'||tab==='payday'||tab==='invest'||r.type===tab)&&(r.type!=='transaction'||r.date.startsWith(month))).map(card).join('')||empty('transaction')}</div><p class="caption">Private data stays in your DreamHub browser storage unless you explicitly activate private cloud sync. Never store account credentials in entries. No money moves through DreamHub.</p>`;}
function reminderPanel(){const overdue=overdueItems(active(store.state),day()),soon=upcomingReminders(active(store.state),new Date(),120);return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">MY GENTLE REMINDER DESK</span><h2>What's coming up?</h2></div><span class="tag">${overdue.length} overdue</span></div><p>${soon.length} items within the next two hours. ${overdue.length} dated tasks, bills or applications need review.</p>${soon.slice(0,5).map(x=>`<div class="category-row"><span>${esc(x.title)}</span><small>${new Date(x.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small></div>`).join('')}<button class="softbutton" data-action="reminder-optin">Enable browser reminders while DreamHub is open</button><p class="caption">Requires browser permission. Only while this page remains open; not push notifications or a background automation service. Untimed entries use 9 AM as a planning reminder, not a confirmed appointment time.</p></section>`;}
function schedulerStudio(){const date=selectedDate||day(),today=active(store.state).filter(r=>r.type==='event'&&r.date===date&&r.tags?.includes('Day Architect')),movement=movementForDate(date);return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">CONNECTED LIFE SCHEDULER ♡</span><h2>Time blocks that respect my actual appointments</h2></div><span class="tag">${today.length} saved blocks</span></div><form id="scheduler-form" class="formgrid"><label>Available from<input type="time" name="start" value="10:00" required></label><label>Until<input type="time" name="end" value="19:00" required></label><label>My energy<select name="energy"><option value="low">Low energy</option><option value="steady" selected>Steady</option><option value="high">High energy</option></select></label><label>Minutes between blocks<input type="number" name="buffer" min="0" max="60" value="10"></label><label class="checklabel span2"><input type="checkbox" name="workout" checked> Include ${esc(movement.name)} when it fits</label><button class="heart-pill">Preview my time blocks ♡</button></form><div id="scheduler-preview" role="status"><p class="caption">The planner checks existing timed events and open tasks, suggests focus windows, and flags overlaps. Preview first; saving is always your choice.</p></div><p class="caption">Saved blocks become editable DreamHub calendar events. This does not write to Google Calendar, send notifications, or run when the site is closed.</p></section>`;}
function movementMetrics(){const keys=[['weight','Weight (lb)'],['neck','Neck (in)'],['leftArm','Left arm (in)'],['rightArm','Right arm (in)'],['bust','Bust (in)'],['waist','Natural waist (in)'],['lowerWaist','Lower waist (in)'],['hips','Hips (in)'],['leftThigh','Left thigh (in)'],['rightThigh','Right thigh (in)'],['leftCalf','Left calf (in)'],['rightCalf','Right calf (in)']],saved=active(store.state).filter(r=>r.type==='note'&&r.tags?.includes('Private body measurements')).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="panel"><div class="panelhead"><div><span class="tiny-label">PRIVATE PROGRESS ARCHIVE</span><h2>Measurements & trends</h2></div><span class="tag">${saved.length} check-ins</span></div><p>Optional. Track strength and how you feel, or record measurements only when useful. These entries stay in your own DreamHub storage and are not committed to GitHub.</p><form id="measurement-form" class="formgrid"><label>Date<input type="date" name="date" value="${day()}" required></label>${keys.map(([k,label])=>`<label>${label}<input type="number" min="0" max="1000" step="0.1" name="${k}" placeholder="Optional"></label>`).join('')}<label class="span2">Notes<textarea name="notes" maxlength="500" placeholder="Energy, strength, clothes fit, progress that isn't a number…"></textarea></label><button class="heart-pill">Save private check-in ♡</button></form><label>Trend to review<select id="metric-select">${keys.map(([k,label])=>`<option value="${k}">${label}</option>`).join('')}</select></label><div id="metric-trend" role="status">${metricTrend('weight')}</div><div class="centeractions"><button class="softbutton" data-action="movement-schedule">Add the next 7 workout sessions to my planner</button></div><p class="caption">The weekly routine is a starting template, not a required schedule. Review before adding; duplicate workouts are skipped.</p></section>`;}
function metricTrend(key){const series=measurementSeries(active(store.state),key);if(!series.length)return '<p class="calmempty">No measurements for this metric yet.</p>';const min=Math.min(...series.map(p=>p.value)),max=Math.max(...series.map(p=>p.value)),range=Math.max(1,max-min),points=series.slice(-20);return `<svg viewBox="0 0 340 120" width="100%" height="120" role="img" aria-label="Measurement trend for ${esc(key)}"><polyline fill="none" stroke="currentColor" stroke-width="3" points="${points.map((p,i)=>`${20+i*300/Math.max(1,points.length-1)},${100-(p.value-min)/range*80}`).join(' ')}"/></svg><p class="caption">${points.length} entries · first ${points[0].value} · latest ${points.at(-1).value}. A chart describes change, not health or worth.</p>`;}
function brainDesk(){const date=selectedDate||day(),items=active(store.state),todays=items.filter(r=>r.date===date&&['event','bill','application'].includes(r.type)),overdue=items.filter(r=>r.type==='task'&&r.status!=='Done'&&r.date<date),plan=planDay(items,date,'steady',180);return `<section class="panel" id="brain-desk"><div class="panelhead"><div><span class="tiny-label">MY EXTERNAL BRAIN · THE DAY ARCHITECT ♡</span><h2>Tell my brain what matters today</h2></div><a href="#inbox" class="textlink">Life inbox ↗</a></div><p>Capture once, choose a realistic day, and leave space between things. No shame, no streaks, no hidden scheduling.</p><form id="brain-capture-form" class="inlineform"><label class="span2">What's on my mind?<input name="thought" required maxlength="240" placeholder="Call the dentist, buy Freyja's supplies, follow up with a client…"></label><button class="heart-pill">Catch this thought ♡</button></form><div class="lowergrid twocol"><div><h3>My day, gently designed</h3><form id="brain-plan-form" class="inlineform"><label>Energy<select name="energy"><option value="low">Low energy</option><option value="steady" selected>Steady</option><option value="high">Ready to focus</option></select></label><label>Time I can give (minutes)<input name="minutes" type="number" min="15" max="720" value="180"></label><button class="softbutton">Make my day plan ♡</button></form><div id="brain-plan-result" role="status">${plan.blocks.filter(b=>b.kind==='focus').length} possible focus tasks · ${plan.appointments.length} appointments today. Adjust energy and time for a detailed plan.</div></div><div><h3>Things needing my attention</h3><p>${todays.length} dated commitments · ${overdue.length} open tasks dated before today.</p><div class="centeractions"><button class="softbutton" data-action="new" data-type="task" data-date="${date}">Add a tiny task</button><button class="softbutton" data-action="new" data-type="event" data-date="${date}">Add an appointment</button></div><p class="caption">Plans are suggestions, not scheduled calendar events. Your saved tasks stay intact.</p></div></div></section>`;}
function movementGarden(){const date=selectedDate||day(),session=movementForDate(date),logs=active(store.state).filter(r=>r.type==='habit'&&r.tags?.includes('Movement Garden')&&r.date===date);return heading('MY BODY, MY RHYTHM','The movement <em>garden.</em>','Strength, stamina, and care—at my pace.','habit')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">TODAY’S MOVEMENT ♡</span><h2>${esc(session.name)}</h2></div><span class="tag">${session.minutes?session.minutes+' min':'Rest'}</span></div><p>Begin with 5 minutes of comfortable warm-up. Rest 60–90 seconds between sets, move with control, and exhale through the harder part. Stop if you feel dizzy, faint, or have chest pain.</p>${session.exercises.map(([name,reps])=>`<div class="category-row"><span>${esc(name)}${exerciseSwaps[name]?`<small>Swap: ${esc(exerciseSwaps[name].join(' / '))}</small>`:''}</span><strong>${esc(reps)}</strong></div>`).join('')}<form id="movement-log-form" class="formgrid"><label>How did it go?<select name="result"><option value="complete">Completed</option><option value="partial">Shorter session</option><option value="rest">Rested instead</option></select></label><label>Effort<select name="effort"><option value="steady">Comfortable challenge</option><option value="easy">Felt easy</option><option value="hard">Felt hard</option></select></label><label class="span2">Notes (optional)<input name="notes" maxlength="400" placeholder="Reps, weights, energy, how I felt…"></label><button class="heart-pill">Save my movement ♡</button></form><p class="caption">${logs.length} session log(s) for this day. Records are stored in your DreamHub data, not GitHub.</p></section><section class="panel"><h2>My weekly movement rhythm</h2><div class="category-row"><span>Monday / Friday</span><strong>Glutes + legs</strong></div><div class="category-row"><span>Wednesday</span><strong>Upper + core</strong></div><div class="category-row"><span>Tuesday / Thursday</span><strong>Walk + mobility</strong></div><div class="category-row"><span>Saturday</span><strong>Fun movement / class</strong></div><div class="category-row"><span>Sunday</span><strong>Rest</strong></div><p class="caption">Start with one or two sets if returning to exercise. Increase reps or resistance gradually, never both at once. No exercise can choose where body fat is lost; strength can develop muscle while overall body composition changes.</p></section>`+movementMetrics();}
function calendar(){const [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1),count=new Date(y,m,0).getDate(),offset=(start.getDay()+6)%7,entries=active(store.state).filter(r=>['event','task','bill','application'].includes(r.type));return heading('A LITTLE ROOM IN MY DAYS','My gentle <em>planner.</em>','Appointments, next steps, and things to look forward to.','event')+brainDesk()+schedulerStudio()+reminderPanel()+`<div class="toolbar"><div class="centeractions"><button class="iconbutton" data-action="prev-month" aria-label="Previous month">←</button><h2>${start.toLocaleString('en',{month:'long',year:'numeric'})}</h2><button class="iconbutton" data-action="next-month" aria-label="Next month">→</button></div><button class="softbutton" data-action="ics">${icon('calendar')} Export events (.ics)</button></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendarblank"></div>').join('')}${Array.from({length:count},(_,i)=>{const date=`${month}-${String(i+1).padStart(2,'0')}`,rs=entries.filter(r=>r.date===date);return `<div class="calendarday ${date===day()?'today':''}"><button class="daynumber" data-action="calendar-date" data-date="${date}" aria-label="Add event for ${date}">${i+1}</button>${rs.slice(0,3).map(r=>`<button class="calendarentry" data-action="edit" data-id="${r.id}">${esc(r.data.time||'')} ${esc(r.title)}</button>`).join('')}${rs.length>3?`<button class="textbutton" data-action="calendar-agenda" data-date="${date}">+${rs.length-3} more</button>`:''}</div>`}).join('')}</div><section class="panel agenda"><div class="panelhead"><h2>${selectedDate?'On '+selectedDate:'This month’s little plans'}</h2><span class="caption">Times follow your current device’s timezone</span></div>${entries.filter(r=>selectedDate?r.date===selectedDate:r.date.startsWith(month)).sort((a,b)=>(a.date+(a.data.time||'')).localeCompare(b.date+(b.data.time||''))).map(r=>`<button class="agenda-row" data-action="edit" data-id="${r.id}"><span>${esc(r.date)}<small>${esc(r.data.time||'All day')}</small></span><strong>${esc(r.title)}</strong><span class="tag">${types[r.type].name}</span></button>`).join('')||'<p class="calmempty">Your calendar has breathing room. Choose a date to make a plan.</p>'}</section>`}
function timerText(){const t=store.state.timer;const sec=t?(t.running?Math.max(0,Math.ceil((t.endAt-Date.now())/1000)):t.remaining):25*60;return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function focus(){return heading('THE REST CAN WAIT','A pocket of <em>possibility.</em>','Make yourself comfortable. One little thing at a time.')+`<div class="focusgrid"><section class="focus-room"><span class="tiny-label">A LITTLE SPACE TO BEGIN</span><div class="clock-orbit"><span>✧</span><div class="focusclock" data-clock>${timerText()}</div><span>♡</span></div><div class="duration-pills">${[5,15,25,45].map(n=>`<button data-action="duration" data-minutes="${n}" class="${(store.state.timer?.duration||25)===n?'selected':''}">${n} min</button>`).join('')}</div><label class="focus-select">What am I giving my attention to?<select id="focus-task"><option value="">Just a little space to focus</option>${records('task').filter(r=>r.status!=='Done').map(r=>`<option value="${r.id}" ${r.id===focusedTask?'selected':''}>${esc(r.title)}</option>`).join('')}</select></label><div class="centeractions"><button class="heart-pill" data-action="focus-start">${icon('heart')} ${store.state.timer?.running?'Pause gently':'Begin my session'}</button><button class="softbutton" data-action="focus-reset">Reset</button></div><p class="caption">Timer survives refresh on this device. No system or closed-browser notifications.</p></section><div><section class="panel"><span class="tiny-label">PUT IT DOWN FOR A MOMENT</span><h2>The distraction parking lot</h2><p>That thought can wait here while you do your thing.</p><form id="parking-form"><label class="sr-only" for="parking">A distracting thought</label><textarea id="parking" name="thought" placeholder="Oh, and also…" required></textarea><button class="softbutton">Park this thought ♡</button></form></section><section class="panel sessionlist"><h2>Little pockets, collected</h2>${store.state.sessions.slice(-5).reverse().map(x=>`<div class="category-row"><span>${new Date(x.at).toLocaleDateString()}<small>${esc(x.title)}</small></span><b>${x.minutes} min</b></div>`).join('')||'<p class="calmempty">Your finished sessions will land here.<br>No streaks to keep up with.</p>'}</section></div></div>`}
function estate(){const rooms=[['treasury','Treasury','coin'],['career','The office','briefcase'],['learning','The library','book'],['habits','Conservatory','flower'],['grimoire','Moon tower','moon'],['studio','The atelier','heart'],['sanctuary','My sanctuary','home'],['memories','The gallery','frame'],['travel','Observatory','compass'],['reviews','Recovery room','tea']];return heading('ALL MY WORLDS, CONNECTED','The <em>dream estate.</em>','A little place to wander. Every room opens the same records you know.')+`<section class="estate-scene"><div class="estate-sky"><span>✦</span><span>☾</span><span>✧</span></div><div class="estate-title">Arabella’s <em>ever after</em></div><div class="estate-rooms">${rooms.map(([r,label,ic],i)=>`<a href="#${r}" class="estate-room estate-room-${i}"><span class="estate-roof"></span><div class="estate-window">${icon(ic)}</div><h2>${label}</h2><small>Come on in ↗</small></a>`).join('')}</div><p>A whole life. A little universe. All yours. ♡</p></section><a href="#home" class="softbutton">${icon('home')} Back to the plain dashboard</a>`}
function rulePage(){return heading('SMALL HELP, ON MY TERMS','The automation <em>atelier.</em>','Clear triggers. Visible results. Nothing sends or spends for you.')+`<section class="panel"><div class="panelhead"><div><span class="tiny-label">ONE HELPFUL LITTLE RECIPE</span><h2>Application → follow-up task</h2></div>${icon('spark')}</div><p>When an application is marked Applied, create a linked task seven days after its application date. Run only when you press “Run my rules.” Each application runs once per rule.</p><div class="centeractions"><button class="heart-pill" data-action="rule-toggle">${icon('heart')} ${store.state.rules.some(x=>x.enabled)?'Pause this rule':'Enable this recipe'}</button><button class="softbutton" data-action="rule-preview">Preview the next run</button><button class="softbutton" data-action="rule-run">Run my rules</button></div><div id="rule-preview" role="status"></div><p class="caption">App-open, manually triggered internal automation. No external integrations or unattended schedules.</p></section><section class="panel" style="margin-top:24px"><h2>Little things, accounted for</h2>${store.state.runs.slice(-20).reverse().map(x=>`<div class="category-row"><span>${new Date(x.at).toLocaleString()}<small>${esc(x.result)}</small></span>${icon('check')}</div>`).join('')||'<p class="calmempty">Your rule runs will be recorded here.</p>'}</section>`}
function searchPage(){let found=active(store.state).filter(r=>!search||`${r.title} ${r.body} ${r.tags.join(' ')} ${types[r.type]?.name||''}`.toLowerCase().includes(search.toLowerCase()));return heading('IT’S SOMEWHERE IN MY UNIVERSE','Find a little <em>something.</em>','Search the titles, writing, tags, and record types in your loaded workspace.')+`<label class="bigsearch">${icon('search')}<input id="global-search" autofocus placeholder="A thought, a dream, a next step…" value="${esc(search)}" aria-label="Search all my records"></label><p class="caption" id="search-count">${found.length} pages in your universe. Sensitive entry previews stay concealed in search.</p><div class="recordgrid" id="search-results">${found.map(r=>r.sensitive?`<article class="recordcard"><span class="tiny-label">PRIVATE ${types[r.type].name}</span><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button><p class="caption">Preview concealed · ${esc(r.date)}</p></article>`:card(r)).join('')||empty('note')}</div>`}
function settings(){const p=store.state.settings;return heading('MAKE YOURSELF AT HOME','My little <em>preferences.</em>','A universe that can meet you where you are.')+`<div class="settingsgrid"><section class="panel"><h2>Make it mine</h2><form id="settings-form"><label>Call me<input name="name" maxlength="50" value="${esc(p.name)}" required></label><label>My palette<select name="theme">${[['rose','Blush & lavender'],['garden','Enchanted garden'],['midnight','Midnight grimoire']].map(([v,l])=>`<option value="${v}" ${p.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Dashboard mode<select name="mode">${[['dream','Dream mode'],['command','Command mode'],['gentle','A gentler day']].map(([v,l])=>`<option value="${v}" ${p.mode===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Room to breathe<select name="density"><option value="cozy" ${p.density==='cozy'?'selected':''}>Cozy</option><option value="compact" ${p.density==='compact'?'selected':''}>Compact</option></select></label><label class="checklabel"><input type="checkbox" name="motion" ${p.motion?'checked':''}> Gentle decorative motion</label><button class="heart-pill">${icon('heart')} Make it mine</button></form></section><section class="panel"><span class="tiny-label">YOUR WORDS BELONG TO YOU</span><h2>My data & little safety net</h2><p>${store.cloud?'<strong>Private cloud connected.</strong> Saved records belong to your invited account. Drafts remain on this device. Refresh to fetch other-device changes.':'<strong>Device-only review version.</strong> Entries save in this browser. Private sign-in and cloud sync aren’t connected.'} This is not end-to-end encryption or a device lock.</p><div class="data-count"><b>${active(store.state).length}</b><span>active records · ${(new Blob([JSON.stringify(store.state)]).size/1024).toFixed(1)} KB of data</span></div><div class="stackbuttons">${store.cloud?'<button class=softbutton data-action=cloud-refresh>Fetch my latest cloud pages</button><button class=softbutton data-action=sign-out>Sign out & clear local drafts</button>':''}<button class="softbutton" data-action="export">Export my full backup (JSON)</button><button class="softbutton" data-action="export-csv">Export my money journal (CSV)</button><button class="softbutton" data-action="export-writing">Export my writing (Markdown)</button><button class="softbutton" data-action="import">Review a backup to import</button><a href="#trash" class="softbutton">Visit the recovery room ↗</a></div><p class="caption">Imports preview first and merge by ID. Conflicts stop the import. Deleted records stay recoverable until you explicitly erase them.</p></section><section class="panel"><h2>My rooms, my choice</h2><p>Hide a room without deleting its records. Restore it here anytime.</p><div class="roomtoggles">${groups.flatMap(x=>x[1]).filter(x=>!['home','settings'].includes(x[0])).map(([id,title])=>`<label class="checklabel"><input type="checkbox" data-room="${id}" ${p.hidden.includes(id)?'':'checked'}>${title}</label>`).join('')}</div></section><section class="panel"><h2>What’s working & what’s next</h2><p>This build includes connected records, draft recovery, trash, exact-cent budgets, mixed feelings, a 78-card reference, local spread draws, planner, focus history, trackers, and manually run follow-up rules.</p><p><strong>Still to connect:</strong> managed authentication, private cloud data and two-device sync. Photo cards stay local. Browser-based workflows have no guaranteed background delivery.</p><p>Rich text, advanced recurrence, drag-and-resize dashboards, attachment vaults, and the full v5 automation engine remain later release work.</p><p class="caption">No paid integrations, AI calls, subscriptions, or bank connections have been enabled.</p></section></div>`}
function trashPage(){const rs=store.state.records.filter(x=>x.deletedAt);return heading('NOT EVERY GOODBYE HAS TO BE FOREVER','The little <em>recovery room.</em>','Restore a page, or permanently erase one after reviewing it.')+`<div class="recordgrid">${rs.map(r=>`<article class="recordcard"><span class="tiny-label">${types[r.type]?.name||r.type} · ${esc(r.deletedAt.slice(0,10))}</span><h3>${esc(r.title)}</h3><div class="cardactions"><button class="softbutton" data-action="restore" data-id="${r.id}">Bring it back ♡</button><button class="textbutton" data-action="purge" data-id="${r.id}">Erase permanently</button></div></article>`).join('')||'<p class="calmempty">Nothing here needs rescuing. ♡</p>'}</div>`}
function render(){try{const focused=document.activeElement?.id;let content=route==='home'?home():route==='focus'?focus():route==='calendar'?calendar():route==='movement'?movementGarden():route==='estate'?estate():route==='rules'?rulePage():route==='settings'?settings():route==='trash'?trashPage():route==='search'?searchPage():routeTypes[route]?modulePage():home();shell(content);if(focused==='global-search')$('#global-search')?.focus();}catch(e){error('This page couldn’t load. Your saved data is still retained. '+e.message)}}
const formValue=(name,value,type='text',options=null)=>`<label>${esc(name)}${options?`<select name="${esc(type)}">${options.map(o=>`<option ${String(value)===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${esc(name)}">${esc(value)}</textarea>`:''}</label>`;
function fieldHtml(key,label,kind,value='',opts=[]){if(kind==='select')return `<label>${esc(label)}<select name="data.${key}">${opts.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;if(kind==='textarea')return `<label class="span2">${esc(label)}<textarea name="data.${key}" rows="3">${esc(value)}</textarea></label>`;return `<label>${esc(label)}<input name="data.${key}" type="${kind==='money'?'text':kind==='integer'?'number':kind}" ${kind==='money'?'inputmode="decimal"':kind==='integer'?'min="1" max="1000" step="1"':kind==='number'?'min="0" max="100" step=".01"':''} value="${esc(value)}"></label>`;}
function getDraft(id){try{return JSON.parse(storage.getItem(draftPrefix+id)||'null')}catch{return null}}
function openEditor(type='note',id=null,preset={}){if($('#editor').open&&!saveDraft())return;if(!types[type])type='note';const existing=id?store.state.records.find(r=>r.id===id):null;editBase=existing?structuredClone(existing):null;writingType=existing?.type||type;formId=existing?.id||'new-'+writingType;const draft=getDraft(formId);if(draft&&editBase)editBase.version=draft.baseVersion;const r=draft?.record||existing||record(writingType,{...preset,data:{...preset.data}});photo=r.data.photo||'';const def=types[writingType],privateType=['journal','diary','mood','dream','reading','ritual'].includes(writingType);$('#editor').innerHTML=`<form id="record-form" data-id="${r.id}" data-type="${writingType}"><div class="editorhead"><div><span class="tiny-label">A LITTLE ROOM FOR ${esc(def.plural)}</span><h2 id="editor-title">${existing?'My':'A fresh'} <em>${def.name.toLowerCase()}.</em></h2></div><button type="button" class="iconbutton" data-action="close-editor" aria-label="Save draft and close">${icon('close')}</button></div><div class="editorbody"><div class="draft-status" id="draft-status">${draft?'Recovered your unsaved draft.':existing?'Your saved page. Edits become a draft until you save.':'A new little beginning. Drafts stay on this device.'}</div><label class="titlefield"><span>Give it a name</span><input name="title" placeholder="A little thought, a big possibility…" value="${esc(r.title==='Untitled'?'':r.title)}" maxlength="240" required></label><div class="formgrid"><label>Date<input type="date" name="date" value="${esc(r.date)}"></label><label>Status<select name="status">${['Now','Next','Later','Done','Applied','Interview','Offer','Closed','Active','Paused','Someday'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div>${writingType==='mood'?`<fieldset class="moodfieldset"><legend>What’s here? Choose the whole mix.</legend><div class="moodselect">${moods.map(m=>{const f=r.data.feelings?.find(x=>x.name===m);return `<label><input type="checkbox" name="feeling" aria-label="Feeling ${m}" value="${m}" ${f?'checked':''}><span>${m}</span><select name="intensity.${m}" aria-label="Intensity for ${m}">${[1,2,3,4,5].map(i=>`<option value="${i}" ${i===(f?.intensity||3)?'selected':''}>${i}/5</option>`).join('')}</select></label>`}).join('')}</div><label>Other feelings (comma separated)<input name="customFeelings" value="${esc((r.data.feelings||[]).filter(f=>!moods.includes(f.name)).map(f=>f.name).join(', '))}" placeholder="Mixy, wistful, quietly proud…"></label></fieldset>`:''}<label>My words<textarea name="body" class="writingarea" placeholder="Whatever you need to put down. It doesn’t have to be perfect.">${esc(r.body)}</textarea></label><div class="formgrid">${def.fields.map(([key,label,kind,opts])=>fieldHtml(key,label,kind,kind==='money'&&Number.isSafeInteger(r.data[key])?(r.data[key]/100).toFixed(2):r.data[key]??(key==='target'?1:kind==='select'?opts[0]:''),opts)).join('')}<label>Energy<select name="energy">${['Low','Medium','High'].map(x=>`<option ${r.energy===x?'selected':''}>${x}</option>`).join('')}</select></label>${['task','project'].includes(writingType)?`<label>Time I want to give it (minutes)<input name="minutes" type="number" min="1" max="1440" value="${r.minutes||15}"></label>`:''}<label class="span2">Little labels (comma separated)<input name="tags" value="${esc(r.tags.join(', '))}" placeholder="Career, home, a new chapter…"></label><label class="span2">Connect this to another page<select name="links" multiple size="3">${active(store.state).filter(x=>x.id!==r.id).map(x=>`<option value="${x.id}" ${r.links.includes(x.id)?'selected':''}>${esc(x.title)} · ${types[x.type]?.name||x.type}</option>`).join('')}</select><small>Optional. Select one or more related pages.</small></label>${['memory','wish','beauty','wardrobe','travel','experience','season'].includes(writingType)?`<label class="span2">A little picture (optional)<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp"><small>Compressed and saved in your local record. Large libraries need cloud storage.</small></label>${photo?'<p class="caption">A picture is attached. <button type="button" class="textbutton" data-action="remove-photo">Remove picture</button></p>':''}`:''}</div><label class="checklabel"><input type="checkbox" name="sensitive" ${r.sensitive||(!existing&&privateType)?'checked':''}> Conceal this entry’s text in global search previews</label>${existing?`<div class=linked-pages><span class=tiny-label>CONNECTED PAGES</span>${active(store.state).filter(x=>r.links.includes(x.id)||x.links.includes(r.id)).map(x=>`<button type=button class=softbutton data-action=edit data-id="${x.id}">${esc(x.title)} ↗</button>`).join('')||'<p class=caption>Link a goal, task, reflection, or other page above.</p>'}</div>${existing.history?.length?`<details class=revision-history><summary>My earlier versions (${existing.history.length})</summary>${existing.history.slice().reverse().map(x=>`<article><h3>Version ${esc(x.version)} · ${esc(x.title)}</h3><p>${esc(x.body||'No body text.')}</p></article>`).join('')}</details>`:''}<p class="caption">Created ${new Date(existing.createdAt).toLocaleString()} · saved version ${existing.version}</p>`:''}<div id="form-error" class="formerror" role="alert"></div></div><div class="editorfoot"><button type="button" class="textbutton" data-action="discard-draft">Discard draft</button><button class="heart-pill" type="submit">${icon('heart')} Save my little page</button></div></form>`;if(!$('#editor').open)$('#editor').showModal();if(draft?.raw){for(const [key,value] of Object.entries(draft.raw)){const el=$('#record-form').querySelector('[name="'+CSS.escape(key)+'"]');if(el&&el.type!=='checkbox'&&!el.hasAttribute('multiple')&&key!=='feeling'){if(el.localName==='select'){for(const opt of el.querySelectorAll('option')){if((opt.getAttribute('value')??opt.textContent)===value)opt.setAttribute('selected','');else opt.removeAttribute('selected');}}else el.value=value;}}}$('#record-form input[name=title]').focus();}
function readForm(validateForm=true){const form=$('#record-form'),f=new FormData(form),type=form.dataset.type,previous=editBase||getDraft(formId)?.record||record(type,{id:form.dataset.id});const r={...previous,id:form.dataset.id,type,title:String(f.get('title')||'').trim(),body:String(f.get('body')||''),date:String(f.get('date')||''),status:String(f.get('status')||'Next'),energy:String(f.get('energy')||'Medium'),minutes:Number(f.get('minutes')||15),tags:String(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),links:f.getAll('links'),sensitive:f.has('sensitive'),data:{...previous.data,photo}};for(const [key,label,kind]of types[type].fields){const raw=f.get('data.'+key);if(kind==='money'){if(raw){try{r.data[key]=moneyToMinor(raw)}catch(e){if(validateForm)throw e;r.data[key]=previous.data[key]||0;}}else r.data[key]=0;}else if(['number','integer'].includes(kind))r.data[key]=Number(raw)||0;else r.data[key]=String(raw||'');}if(type==='habit'){r.data.logs=previous.data.logs||[];if(!r.data.target)r.data.target=1;}if(type==='mood'){r.data.feelings=f.getAll('feeling').map(name=>({name,intensity:Number(f.get('intensity.'+name))||3}));String(f.get('customFeelings')||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(name=>{if(!r.data.feelings.some(x=>x.name===name))r.data.feelings.push({name,intensity:3});});}if(validateForm&&!r.title)throw Error('Give this page a little name before saving.');return r;}
function saveDraft(){try{const r=readForm(false);storage.setItem(draftPrefix+formId,JSON.stringify({record:r,baseVersion:editBase?.version||null,at:now(),raw:Object.fromEntries(new FormData($('#record-form')).entries())}));$('#draft-status').textContent='Draft kept on this device · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});return true;}catch(e){error('Your draft could not be saved. Keep this editor open and copy your writing before leaving. '+e.message);return false}}
function download(content,name,mime='text/plain'){const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function confirmAction(title,body,action,label='Yes, continue'){return new Promise(resolve=>{$('#confirm').innerHTML=`<h2 id="confirm-title">${esc(title)}</h2><p>${esc(body)}</p><div class="centeractions"><button class="softbutton" id="cancel-confirm">Keep it as it is</button><button class="heart-pill" id="accept-confirm">${esc(label)}</button></div>`;$('#confirm').showModal();$('#cancel-confirm').onclick=()=>{$('#confirm').close();resolve(false)};$('#accept-confirm').onclick=()=>{$('#confirm').close();resolve(true)};$('#confirm').oncancel=()=>resolve(false);});}
async function handleAction(b){const a=b.dataset.action,id=b.dataset.id,r=id?store.state.records.find(x=>x.id===id):null;
if(a==='rhythm-complete'){const template=homeRhythms.find(t=>t.id===id);if(!template)return;if(!rhythmDue(records('home'),day()).some(t=>t.id===id)){toast('Already complete or not due ♡');return;}await act(()=>store.put(record('home',{title:template.title,date:day(),status:'Done',tags:['Weekly rhythm',template.category],data:{category:'Cleaning & care',rhythmId:id}})),'Your weekly rhythm is complete ♡');return;}
if(a==='closet-shuffle'){outfitSeed++;render();return;}
if(a==='home-add'){const title=b.dataset.title;if(!title)return;if(records('home').some(r=>r.title===title&&r.date===day()&&r.status!=='Done')){toast('Already on today’s list ♡');return;}await act(()=>store.put(record('home',{title,date:day(),status:'Next',data:{category:'Cleaning & care'}})),'Added to your home reset ♡');return;}
if(a==='beauty-filter'){beautyCategory=b.dataset.category||'All';render();return;}
if(a==='beauty-day'){const current=new Date((selectedDate||day())+'T12:00:00');current.setDate(current.getDate()+Number(b.dataset.offset||0));selectedDate=current.getFullYear()+'-'+String(current.getMonth()+1).padStart(2,'0')+'-'+String(current.getDate()).padStart(2,'0');render();return;}
if(a==='beauty-complete'){const ritual=ritualFor(id),date=selectedDate||day();if(!ritual)return;if(completedRituals(active(store.state),date).has(id)){error('Already recorded for this day.');return;}await act(()=>store.put(record('habit',{title:ritual.name,date,status:'Done',tags:['Beauty Ritual',ritual.category],minutes:ritual.minutes,data:{target:1,rhythm:ritualFrequency(ritual.when),logs:[date],ritualId:id}})),'A little care, beautifully done. ♡');return;}
if(a==='beauty-save'){const ritual=ritualFor(id);if(!ritual)return;const exists=active(store.state).some(r=>r.type==='beauty'&&r.data?.ritualId===id);if(exists){error('This ritual is already in your cabinet. You can edit it there.');return;}await act(()=>store.put(record('beauty',{title:ritual.name,body:ritual.steps.map((x,i)=>String(i+1)+'. '+x).join('\n')+'\n\n'+ritual.note,tags:['Care routine',ritual.category],data:{category:ritual.category==='Wellness'?'Body':ritual.category==='Grooming'?'Body':ritual.category==='Life admin'?'Appointments':ritual.category==='Home'?'Body':ritual.category,routine:ritual.when,ritualId:id}})),'Editable ritual saved to your beauty cabinet. ♡');return;}
if(a==='reminder-optin'){if(!('Notification' in window)){error('This browser does not support desktop notifications. Your in-app reminders still work.');return;}const permission=await Notification.requestPermission();if(permission!=='granted'){error('Notifications were not enabled.');return;}try{storage.setItem('dreamhub-reminders-optin','yes');}catch{error('Browser storage is unavailable, so reminders cannot stay enabled.');return;}startLocalReminders();error('Browser reminders enabled while DreamHub is open.');}
if(a==='movement-schedule'){const dates=weeklyWorkoutDates(selectedDate||day(),7),planned=dates.map(date=>({date,session:movementForDate(date)})).filter(x=>x.session.kind!=='rest'&&x.session.minutes>0);if(!await confirmAction('Schedule this week’s movement?','Adds '+planned.length+' editable workout events to your DreamHub calendar, without changing other appointments. Duplicate sessions will be skipped.',null,'Add my workouts'))return;await act(()=>store.update(state=>{for(const {date,session} of planned){if(state.records.some(r=>!r.deletedAt&&r.type==='event'&&r.date===date&&r.tags?.includes('Movement Garden')))continue;state.records.push(record('event',{title:session.name,date,tags:['Movement Garden'],body:'Suggested workout. Set a time when you are ready.',data:{time:'',endTime:'',place:'',sessionKind:session.kind}}));}}),'Workout sessions added to your DreamHub calendar. ♡');}
if(a==='money-starters'){const existing=records();await act(()=>store.update(state=>{for(const b of starterBills){if(state.records.some(r=>!r.deletedAt&&r.type==='bill'&&r.title===b.name))continue;state.records.push(record('bill',{title:b.name,body:'Starter reference · '+b.verified+(b.note?' · '+b.note:''),data:{amount:b.amount,cadence:b.cadence==='Every two weeks'?'Monthly':b.cadence,category:b.category}}));}for(const [name,target] of starterVaults){if(state.records.some(r=>!r.deletedAt&&r.type==='saving'&&r.title===name))continue;state.records.push(record('saving',{title:name,data:{amount:0,target}}));}}),'Starter references added. Review every amount and cadence before planning.');}
if(a==='new')openEditor(b.dataset.type,null,{status:b.dataset.status||'Next',date:b.dataset.date||day(),tags:route==='studio'?['Studio']:route==='career'?['Career']:[],data:b.dataset.stage?{stage:b.dataset.stage}:{}});
if(a==='quick'){openEditor('note');$('#editor-title').textContent='Let it land here. ♡';}
if(a==='edit')openEditor(r.type,r.id);
if(a==='close-editor'){if(saveDraft())$('#editor').close();}
if(a==='discard-draft'&&await confirmAction('Let this draft go?','This removes the unsaved draft. Your previously saved entry stays as it is.',null,'Discard this draft')){storage.removeItem(draftPrefix+formId);$('#editor').close();}
if(a==='favorite')await act(()=>store.put({...r,favorite:!r.favorite},r.version));
if(a==='complete')await act(()=>store.put({...r,status:r.status==='Done'?'Next':'Done'},r.version),r.status==='Done'?'Back in your next steps.':'A little progress, made. ♡');
if(a==='trash'){if(await act(()=>store.trash(id),'Moved to the recovery room. You can bring it back in Settings.')){const msg=$('#message');msg.innerHTML+=' <button id="undo-trash">Undo</button>';$('#undo-trash').onclick=()=>act(()=>store.restore(id),'Back where it belongs.');}}
if(a==='restore')await act(()=>store.restore(id),'Welcome back, little page.');
if(a==='purge'&&await confirmAction('Erase this page permanently?','This cannot be undone in Dreamhub. It may still exist in any backups you exported.',null,'Erase permanently'))await act(()=>store.update(s=>{s.records=s.records.filter(x=>x.id!==id);s.records.forEach(x=>x.links=x.links.filter(l=>l!==id));}),'Permanently erased.');
if(a==='convert')openEditor('task',null,{title:r.title,body:r.body,links:[r.id],tags:[...r.tags]});
if(a==='habit-log'){if(r.status==='Paused'){toast('This rhythm is paused. Open it to resume when you’re ready.');return;}await act(()=>store.put({...r,data:{...r.data,logs:[...(r.data.logs||[]),day()]}},r.version),'A little care, collected.');}
if(a==='mode')await act(()=>store.update(s=>s.settings.mode=s.settings.mode==='command'?'dream':'command'));
if(a==='gentle')await act(()=>store.update(s=>s.settings.mode=s.settings.mode==='gentle'?'dream':'gentle'));
if(a==='menu'){mobile=!mobile;render();}
if(a==='search'){location.hash='search';requestAnimationFrame(()=>$('#global-search')?.focus());}
if(a==='settings')location.hash='settings';
if(a==='dismiss-error')$('#persistent-error').hidden=true;
if(a==='mood')openEditor('mood',null,{title:'A little check-in',data:{feelings:[{name:b.dataset.mood==='Mixy'?'Mixy':b.dataset.mood,intensity:3}]}});
if(a==='filter-type'){tab=b.dataset.type;render();}if(a==='favorites'){tab='all';filter='';const original=listFor(route).filter(r=>r.favorite);$('#record-results').innerHTML=original.length?original.map(card).join(''):'<p class="calmempty">Tap a heart on a page to keep it close.</p>';}
if(a==='grimoire-tab'){tab=b.dataset.tab;render();}if(a==='money-tab'){tab=b.dataset.tab;render();}
if(a==='draw'){draw=drawCards();render();}if(a==='save-spread')openEditor('reading',null,{title:'A moment with myself',data:{cards:draw.map((c,i)=>`${['What I’m carrying','What needs care','A possible next step'][i]}: ${c.name} (${c.isReversed?'Reversed':'Upright'})`).join('\n')}});
if(a==='calendar-date')openEditor('event',null,{date:b.dataset.date});if(a==='calendar-agenda'){selectedDate=b.dataset.date;render();$('.agenda').scrollIntoView({behavior:store.state.settings.motion?'smooth':'auto'});}
if(a==='prev-month'||a==='next-month'){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()+(a==='next-month'?1:-1));month=day(d).slice(0,7);selectedDate='';render();}
if(a==='ics'){const escapeIcs=t=>String(t).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Arabella Dreamhub//EN',...records('event').filter(x=>x.date).flatMap(r=>['BEGIN:VEVENT',`UID:${r.id}@dreamhub`,`DTSTAMP:${now().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,r.data.time?`DTSTART:${r.date.replaceAll('-','')}T${r.data.time.replace(':','')}00`:`DTSTART;VALUE=DATE:${r.date.replaceAll('-','')}`,r.data.endTime?`DTEND:${r.date.replaceAll('-','')}T${r.data.endTime.replace(':','')}00`:'',`SUMMARY:${escapeIcs(r.title)}`,`DESCRIPTION:${escapeIcs(r.body)}`,'END:VEVENT'].filter(Boolean)),'END:VCALENDAR'].join('\r\n');download(data,'dreamhub-calendar.ics','text/calendar');toast('Exported local-time events. Review timezone when importing elsewhere.');}
if(a==='duration'){const n=Number(b.dataset.minutes);if(store.state.timer?.running&&!await confirmAction('Start a different little session?','This resets the current timer. Finished sessions remain in history.',null,'Reset my timer'))return;await act(()=>store.update(s=>s.timer={duration:n,remaining:n*60,running:false,endAt:null,taskId:focusedTask}));}
if(a==='focus-start'){const t=store.state.timer||{duration:25,remaining:1500,running:false};await act(()=>store.update(s=>s.timer=t.running?{...t,running:false,remaining:Math.max(0,Math.ceil((t.endAt-Date.now())/1000))}:{...t,running:true,endAt:Date.now()+(t.remaining||t.duration*60)*1000,taskId:focusedTask}));}
if(a==='focus-reset'&&await confirmAction('Begin again?','Reset this timer without changing finished sessions.',null,'Reset gently'))await act(()=>store.update(s=>s.timer=null));
if(a==='rule-toggle')await act(()=>store.update(s=>{if(!s.rules.length)s.rules.push({id:uid(),kind:'application-followup',enabled:true});else s.rules[0].enabled=!s.rules[0].enabled;}));
if(a==='rule-preview'){const s=structuredClone(store.state),n=runRules(s);$('#rule-preview').textContent=`This run would create ${n} linked follow-up task${n===1?'':'s'}. No messages or external changes.`;}
if(a==='rule-run')await act(()=>store.update(s=>{const n=runRules(s);if(!n)toast('No new eligible applications. Nothing changed outside Dreamhub.');}),'Internal run recorded. No external actions.');
if(a==='remove-photo'){photo='';saveDraft();toast('Picture removed from this draft. Save to update your page.');}
if(a==='cloud-refresh')await act(()=>store.refresh(),'Latest cloud pages loaded.');
if(a==='sign-out'&&await confirmAction('Close my private universe?','This clears this account’s drafts from this browser, then signs out. Save or export anything unfinished first.',null,'Sign out')){for(let i=storage.length-1;i>=0;i--){const k=storage.key(i);if(k?.startsWith(draftPrefix))storage.removeItem(k);}const result=await cloud.client.auth.signOut();if(result.error)throw result.error;location.reload();}
if(a==='export')download(JSON.stringify({format:'dreamhub',exportedAt:now(),state:store.state},null,2),`arabella-dreamhub-${day()}.json`,'application/json');
if(a==='raw-export')download(storage.getItem(KEY)||'',`dreamhub-original-${day()}.txt`);
if(a==='export-csv'){const c=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['ID','Date','Title','Direction','Amount USD','Space','Category'],...records('transaction').map(r=>[r.id,r.date,r.title,r.data.direction,(r.data.amount/100).toFixed(2),r.data.scope,r.data.category])];download('\uFEFF'+rows.map(row=>row.map(c).join(',')).join('\r\n'),`dreamhub-money-${day()}.csv`,'text/csv');}
if(a==='export-writing')download(records().filter(r=>['journal','diary','ritual','reading','dream','note','review'].includes(r.type)).map(r=>`# ${r.title}\n\n${r.date} · ${types[r.type].name}\n\n${r.body}\n\n${Object.entries(r.data).filter(([k,v])=>typeof v==='string'&&v&&!['photo','url'].includes(k)).map(([k,v])=>`## ${k}\n${v}`).join('\n\n')}`).join('\n\n---\n\n'),`dreamhub-writing-${day()}.md`,'text/markdown');
if(a==='import')$('#backup-input').click();
}
document.addEventListener('change',e=>{if(e.target.id==='metric-select'&&$('#metric-trend'))$('#metric-trend').innerHTML=metricTrend(e.target.value);});
let localReminderInterval=null;const notifiedThisSession=new Set();
function startLocalReminders(){let optedIn=false;try{optedIn=storage.getItem('dreamhub-reminders-optin')==='yes';}catch{}if(localReminderInterval||!optedIn||!('Notification' in window)||Notification.permission!=='granted')return;const check=()=>{for(const r of upcomingReminders(active(store.state),new Date(),10)){const key=r.id+':'+r.at;if(notifiedThisSession.has(key))continue;notifiedThisSession.add(key);new Notification('Arabella’s World ♡',{body:r.title+' · coming up soon',tag:key});}};check();localReminderInterval=setInterval(check,60000);}
startLocalReminders();
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b).catch(e=>error(e.message));});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;
if(f.id==='record-form'){try{const r=readForm();if(r.type==='habit'&&(!Number.isInteger(r.data.target)||r.data.target<1))throw Error('Choose a whole-number target greater than zero.');if(r.type==='event'&&r.data.time&&r.data.endTime&&r.data.endTime<=r.data.time)throw Error('End time must follow the start time on the selected date.');const draft=getDraft(formId),expected=draft?.baseVersion??editBase?.version??null;if(await act(()=>store.put(r,expected),'Saved, with a little love. ♡')){storage.removeItem(draftPrefix+formId);$('#editor').close();}}catch(e){$('#form-error').textContent=e.message;}return;}
if(f.id==='payday-form'){try{const d=new FormData(f),income=moneyToMinor(d.get('income')),input={income,unpaidEssentials:moneyToMinor(d.get('essentials')),minimums:moneyToMinor(d.get('minimums')),taxes:moneyToMinor(d.get('taxes')),buffer:moneyToMinor(d.get('buffer'))},result=allocateIncome(input);const labels={debt:'Extra credit card payoff',emergency:'Emergency fund',apartment:'Apartment vault',car:'Car vault',travel:'Travel vault',house:'House vault'};const target=$('#payday-result');target.innerHTML=`<div class="money-stats"><div><span>RESERVE FIRST</span><strong>${dollars(result.reserved)}</strong></div><div><span>AVAILABLE FOR GOALS</span><strong>${dollars(result.remaining)}</strong></div><div><span>UNFUNDED COMMITMENTS</span><strong>${dollars(result.shortfall)}</strong></div></div>`+Object.entries(result.allocation).map(([k,v])=>`<div class="category-row"><span>${labels[k]}</span><b>${dollars(v)}</b></div>`).join('')+`<p class="caption">Planning proposal only. No transaction saved or money transferred. Verify available cash and all remaining commitments before spending.</p><button type="button" class="softbutton" id="save-payday">Record this received income ♡</button>`;$('#save-payday').onclick=async()=>{await act(()=>store.put(record('transaction',{title:String(d.get('source'))+' received',date:day(),data:{amount:income,direction:'Income',scope:'Personal',category:d.get('source')==='Studio owner pay'?'Client revenue':'Paycheck'}})),'Income logged. No transfers were made.');};}catch(e){error(e.message);}return;}
if(f.id==='utilization-form'){try{const d=new FormData(f),balance=moneyToMinor(d.get('balance')),limit=moneyToMinor(d.get('limit'));if(!limit)throw Error('Enter a positive credit limit.');$('#utilization-result').textContent=`Current utilization: ${(balance/limit*100).toFixed(1)}%. Pay ${dollars(cardPaydown(balance,limit,.30))} to reach 30%, or ${dollars(cardPaydown(balance,limit,.10))} to reach 10%.`;}catch(e){error(e.message)}return;}
if(f.id==='investment-form'){try{const d=new FormData(f),m=moneyToMinor(d.get('monthly')),years=Number(d.get('years')),rate=Number(d.get('rate'))/100;if(years<1||years>50||rate<0||rate>.15)throw Error('Check the years and annual return.');$('#investment-result').textContent=`Illustrative portfolio: ${dollars(futureValue(m,years,rate))} after ${years} years, including ${dollars(m*years*12)} of your own deposits. Not a forecast.`;}catch(e){error(e.message)}return;}
if(f.id==='scheduler-form'){try{const d=new FormData(f),date=selectedDate||day(),p=scheduleDay(active(store.state),date,{start:String(d.get('start')),end:String(d.get('end')),energy:String(d.get('energy')),buffer:Number(d.get('buffer')),includeWorkout:d.has('workout'),workout:movementForDate(date)});const output=$('#scheduler-preview');output.innerHTML=`<p><strong>${p.blocks.length} suggested blocks</strong> · ${p.appointments.length} existing appointments · ${p.skipped.length} could not fit.</p>`+p.conflicts.map(x=>`<p class="warning">Overlapping appointments: ${esc(x.join(' / '))}</p>`).join('')+p.blocks.map(x=>`<div class="category-row"><span>${hhmm(x.start)}–${hhmm(x.end)} · ${esc(x.title)}</span><span class="tag">${esc(x.kind)}</span></div>`).join('')+`<p class="caption">Review these suggestions. No appointments have been changed.</p><button type="button" class="heart-pill" id="approve-schedule">Save approved blocks to DreamHub ♡</button>`;$('#approve-schedule').onclick=async()=>{const existing=active(store.state).filter(r=>r.type==='event'&&r.date===date&&r.tags?.includes('Day Architect'));const ids=new Set(existing.map(r=>r.data?.sourceId));const pending=p.blocks.filter(x=>!ids.has(x.id));if(!pending.length){error('These blocks have already been saved.');return;}await act(()=>store.update(state=>{for(const x of pending)state.records.push(record('event',{title:x.title,date,tags:['Day Architect',x.kind],links:x.kind==='task'?[x.id]:[],data:{time:hhmm(x.start),endTime:hhmm(x.end),place:'',sourceId:x.id}}));}),'Approved blocks saved to your calendar. ♡');};}catch(e){error(e.message)}return;}
if(f.id==='measurement-form'){try{const d=new FormData(f),data={};for(const k of ['weight','neck','leftArm','rightArm','bust','waist','lowerWaist','hips','leftThigh','rightThigh','leftCalf','rightCalf']){const raw=String(d.get(k)||'').trim();if(raw){const n=Number(raw);if(!Number.isFinite(n)||n<=0||n>1000)throw Error('Check your '+k+' measurement.');data[k]=n;}}if(!Object.keys(data).length&&!String(d.get('notes')||'').trim())throw Error('Enter a measurement or note.');await act(()=>store.put(record('note',{title:'Private progress check-in',date:String(d.get('date')),body:String(d.get('notes')||''),tags:['Private body measurements'],sensitive:true,data})),'Private progress check-in saved. ♡');}catch(e){error(e.message)}return;}
if(f.id==='movement-log-form'){try{const d=new FormData(f),date=selectedDate||day(),result=String(d.get('result')),effort=String(d.get('effort')),session=movementForDate(date),note=String(d.get('notes')||'');await act(()=>store.put(record('habit',{title:session.name,date,body:note,tags:['Movement Garden'],status:result==='complete'?'Done':'Next',data:{rhythm:'Weekly',target:1,logs:[],sessionResult:result,effort,progression:progressionNote(result==='complete',effort)}})),'Movement saved in your garden. ♡');}catch(e){error(e.message)}return;}
if(f.id==='brain-capture-form'){try{const d=new FormData(f),parsed=parseCapture(d.get('thought'));await act(()=>store.put(record('note',{title:parsed.title,body:String(d.get('thought')),date:parsed.date||day(),tags:['Brain capture','Needs sorting']})),'Captured in your Life Inbox. ♡');}catch(e){error(e.message)}return;}
if(f.id==='brain-plan-form'){try{const d=new FormData(f),plan=planDay(active(store.state),selectedDate||day(),d.get('energy'),Number(d.get('minutes')));$('#brain-plan-result').innerHTML=`<p><strong>${plan.appointments.length} appointments</strong> · ${plan.unscheduled} other tasks can wait.</p>`+plan.appointments.map(r=>`<div class="category-row"><span>${esc(r.data.time||'All day')} · ${esc(r.title)}</span></div>`).join('')+plan.blocks.map(b=>`<div class="category-row"><span>${b.kind==='break'?'☕ ': '♡ '}${esc(b.title)}</span><b>${b.minutes} min</b></div>`).join('')+`<p class="caption">${plan.remaining} unassigned minutes. Suggested blocks only; nothing was automatically moved or booked.</p>`;}catch(e){error(e.message)}return;}
if(f.id==='salary-form'){try{const d=new FormData(f),rate=moneyToMinor(d.get('hourly')),hours=Number(d.get('hours')),weeks=Number(d.get('weeks')),annual=Math.round(rate*hours*weeks);$('#salary-result').textContent=`${dollars(annual)} gross per year · ${dollars(Math.round(annual/12))} average gross per month.`;}catch(e){error(e.message)}}
if(f.id==='budget-form'){try{const limit=moneyToMinor(new FormData(f).get('limit'));await act(()=>store.update(s=>s.budgetPlans[month]={limit}),'Your plan is saved for this month.');}catch(e){error(e.message)}}
if(f.id==='debt-form'){try{const d=new FormData(f),r=amortize(moneyToMinor(d.get('balance')),Number(d.get('apr')),moneyToMinor(d.get('payment')));$('#debt-result').textContent=r.error||`At these assumptions: ${r.months} months and approximately ${dollars(r.interest)} interest.`;}catch(e){error(e.message)}}
if(f.id==='parking-form'){const title=String(new FormData(f).get('thought')).trim();if(title)await act(()=>store.put(record('note',{title:title.slice(0,240),body:title,tags:['Focus parking lot']})),'Parked safely in your inbox.');}
if(f.id==='settings-form'){const d=new FormData(f);await act(()=>store.update(s=>{s.settings={...s.settings,name:String(d.get('name')).trim()||'Arabella',theme:d.get('theme'),mode:d.get('mode'),density:d.get('density'),motion:d.has('motion')};}),'A little more you. ♡');}
});
document.addEventListener('input',e=>{if(e.target.closest('#record-form')&&e.target.type!=='file'){saveDraft();}if(e.target.matches('[data-filter]')){filter=e.target.value;let rs=listFor(route).filter(r=>(tab==='all'||r.type===tab)&&`${r.title} ${r.body} ${r.tags.join(' ')} ${JSON.stringify(r.data)}`.toLowerCase().includes(filter.toLowerCase()));if(route==='tasks'){const pos=e.target.selectionStart;render();const input=$('[data-filter]');input.focus();input.setSelectionRange(pos,pos);}else if($('#record-results'))$('#record-results').innerHTML=rs.length?rs.map(card).join(''):'<p class="calmempty">No pages match yet.</p>';}if(e.target.id==='global-search'){search=e.target.value;const rs=records().filter(r=>`${r.title} ${r.body} ${r.tags.join(' ')} ${types[r.type]?.name||''}`.toLowerCase().includes(search.toLowerCase()));$('#search-results').innerHTML=rs.map(r=>r.sensitive?`<article class="recordcard"><button class="recordtitle" data-action="edit" data-id="${r.id}"><h3>${esc(r.title)}</h3></button><p class="caption">Private preview concealed</p></article>`:card(r)).join('')||'<p class="calmempty">No pages found. Try another little word.</p>';$('#search-count').textContent=rs.length+' matching pages.';}if(e.target.matches('[data-tarot-search]'))document.querySelectorAll('[data-card-name]').forEach(c=>c.hidden=!c.dataset.cardName.includes(e.target.value.toLowerCase()));});
document.addEventListener('change',async e=>{if(e.target.id==='money-month'){month=e.target.value||day().slice(0,7);render();}if(e.target.id==='focus-task')focusedTask=e.target.value;if(e.target.dataset.room){const room=e.target.dataset.room;await act(()=>store.update(s=>s.settings.hidden=e.target.checked?s.settings.hidden.filter(x=>x!==room):[...new Set([...s.settings.hidden,room])]),'Your rooms are arranged.');}if(e.target.id==='photo-input'&&e.target.files[0]){const file=e.target.files[0];try{if(file.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG or WebP picture under 8 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photo=canvas.toDataURL('image/webp',.65);if(photo.length>600000)throw Error('This picture is still too large. Choose a smaller photo.');saveDraft();toast('A little picture added to your draft.');}catch(e){photo='';error(e.message)}}});
$('#backup-input').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Choose a backup under 10 MB.');const json=JSON.parse(await file.text());let incoming,warnings=[];if(json.version===1){const r=migrateLegacy(json);incoming=r.state;warnings=r.warnings;}else incoming=validate(json.state||json);const existing=new Set(store.state.records.map(r=>r.id)),newCount=incoming.records.filter(r=>!existing.has(r.id)).length;pendingImport=incoming;if(await confirmAction('Bring these pages into my universe?',`${incoming.records.length} records in the file. ${newCount} new IDs. Existing conflicts stop the import. ${warnings.join(' ')} Your existing data will not be replaced.`,null,'Merge these pages'))await act(()=>store.import(pendingImport),'Your pages have landed. ♡');}catch(e){error('Import stopped: '+e.message)}finally{e.target.value='';pendingImport=null;}});
$('#editor').addEventListener('cancel',e=>{if(!saveDraft())e.preventDefault();});
window.addEventListener('hashchange',()=>{if($('#editor').open){if(!saveDraft()){location.hash=route;return;}$('#editor').close();}route=location.hash.slice(1)||'home';tab='all';filter='';mobile=false;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key===KEY){try{if(store.cloud)return;store.state=store.read();if(!$('#editor').open)render();else toast('Another tab changed your data. Your editor draft stays here; conflicts will be checked on save.');}catch(e){error(e.message)}}});
window.addEventListener('beforeunload',e=>{if($('#editor').open&&!saveDraft()){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#editor').open){if(!saveDraft())return;$('#editor').close();}location.hash='search';requestAnimationFrame(()=>$('#global-search')?.focus());}});
let ticking=false;setInterval(async()=>{const t=store.state.timer;document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=timerText());if(t?.running&&t.endAt<=Date.now()&&!ticking){ticking=true;try{await store.update(s=>{if(!s.timer?.running||s.timer.endAt>Date.now())return;const title=s.records.find(r=>r.id===s.timer.taskId)?.title||'A little focus';s.sessions.push({id:uid(),at:now(),title,minutes:s.timer.duration});s.timer={...s.timer,running:false,remaining:0};});render();toast('Your little focus session is complete. Time for a breath. ♡');}catch(e){error('Session completion could not be saved: '+e.message)}finally{ticking=false;}}},500);
render();
export {store,render,openEditor,readForm,saveDraft,handleAction};
function pipelinePage(){const career=route==='career',rs=records(career?'application':'client'),columns=career?['Applied','Interview','Offer','Closed']:['Prospect','Conversation','Proposal','In progress','Delivered','Closed'];const stage=r=>career?(columns.includes(r.status)?r.status:'Applied'):(columns.includes(r.data.stage)?r.data.stage:'Prospect');return heading(career?'STABILITY, SKILLS & A FRESH START':'A LITTLE STRUCTURE FOR MY CREATIVE AMBITION',career?'My next <em>beautiful chapter.</em>':'A. Halliwell <em>Studio.</em>',career?'A clear view of applications and possibilities. Your actual experience, your next move.':'Prospects, proposals, delivery. Keep creative work moving at a human pace.',career?'application':'client')+`<div class="pipeline-stats"><div><strong>${rs.length}</strong><span>${career?'applications logged':'studio connections'}</span></div><div><strong>${rs.filter(r=>stage(r)===(career?'Interview':'Proposal')).length}</strong><span>${career?'interviews':'proposals'}</span></div><div><strong>${career?rs.filter(r=>stage(r)==='Offer').length:dollars(rs.filter(r=>['Proposal','In progress'].includes(stage(r))).reduce((s,r)=>s+(r.data.amount||0),0))}</strong><span>${career?'offers':'quoted pipeline · not received cash'}</span></div></div><div class="pipelineboard">${columns.map(col=>`<section class=boardcolumn><div class=boardheading><h2>${col}</h2><span>${rs.filter(r=>stage(r)===col).length}</span></div>${rs.filter(r=>stage(r)===col).map(r=>`<article class=boardcard><span class=tiny-label>${esc(r.data.company||'A new possibility')}</span><button class=recordtitle data-action=edit data-id="${r.id}"><h3>${esc(r.title)}</h3></button><p>${esc(career?r.data.salary||'Compensation not entered':r.data.scope||'A scope worth exploring.')}</p><small>${esc(r.date||'Date not set')}</small><div class=cardactions><button class=textbutton data-action=edit data-id="${r.id}">My next move ↗</button>${safeUrl(r.data.url)?`<a class=iconbutton href="${esc(safeUrl(r.data.url))}" target=_blank rel="noopener noreferrer" aria-label="Open saved website">${icon('arrow')}</a>`:''}</div></article>`).join('')}<button class=boardadd data-action=new data-type="${career?'application':'client'}" data-status="${career?col:'Next'}" data-stage="${col}">${icon('plus')} A new possibility</button></section>`).join('')}</div>${career?`<section class="panel compensation"><span class=tiny-label>KNOW MY NUMBERS</span><h2>A little compensation clarity</h2><form id=salary-form class=inlineform><label>Hourly rate (USD)<input name=hourly inputmode=decimal required></label><label>Hours each week<input name=hours type=number value=40 min=1 max=100 required></label><label>Paid weeks per year<input name=weeks type=number value=52 min=1 max=52 required></label><button class=heart-pill>Compare my income ♡</button></form><div id=salary-result role=status></div><p class=caption>Gross arithmetic only. Taxes, benefits, unpaid time, overtime and actual schedules can change take-home pay.</p></section>`:`<section class=panel style="margin-top:25px"><h2>Studio next steps</h2>${records('task').filter(x=>x.tags.includes('Studio')).map(miniTask).join('')||'<p class=calmempty>No next steps yet. A tiny action can start a whole project.</p>'}<button class=softbutton data-action=new data-type=task data-studio=true>Add a studio step ♡</button></section>`}`;}
